contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }
	receive() external payable {}
	function test(uint256 v) public {
		require(v > 0);
		require(address(this).balance >= v);
		uint256 preC = address(c).balance;
		address own = c.owner();
		uint256 preOwner = address(own).balance;
		(bool ok, ) = address(c).call{value: v}(abi.encodeWithSelector(c.go.selector));
		assert(!ok || address(c.owner()).balance - preOwner == preC);
	}
}

