contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }
	receive() external payable {}
	fallback() external payable {}

	function check(uint256 f) public {
		require(f > 0);
		require(address(this).balance >= f);

		// pre-fund c through its payable fallback
		(bool okF, ) = address(c).call{value: f}("");
		require(okF);

		address o = c.owner();
		uint256 ownerBal0 = address(o).balance;

		// go() with zero msg.value: in P the target gets 0 and the
		// pre-existing balance f is swept to the owner
		c.go{value: 0}();

		uint256 ownerBal1 = address(o).balance;
		assert(ownerBal1 - ownerBal0 == f);
	}
}

