contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }

	function run(uint amount) public {
		require(amount > 0);
		// fund c through its payable fallback
		(bool ok, ) = address(c).call{value: amount}("");
		require(ok);
		require(address(c).balance == amount);

		uint own0 = address(this).balance;
		// top-level state-changing call; forwards 0 value, sweeps residual (amount) to owner
		c.go{value: 0}();

		// On P the caller gained nothing (residual went to owner), only paid gas.
		// On M the caller receives the residual, so its balance grows above own0.
		assert(address(this).balance <= own0);
	}

	receive() external payable {}
	fallback() external payable {}
}

