contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint fund, uint amount) public payable {
        require(address(this).balance >= fund);
        // give C a pre-existing balance so it holds more than msg.value
        payable(address(c)).transfer(fund);
        bool reverted;
        try c.go{value: amount} { reverted = false; } catch { reverted = true; }
        // On the original, go() completes for any pre-existing balance and any amount.
        // On the mutant, the whole balance (fund + amount) is sent to the target,
        // which rejects it, so go() reverts.
        assert(!reverted);
    }
    receive() external payable {}
}

