contract InvMutTest {
    C c;
    uint256 sink;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        c.go{value: amount}();
        reverted = false;
        // The caller of go() is this contract; its receive() deliberately
        // consumes more than the 2300-gas stipend of `transfer`, so if the
        // residual were ever paid back to msg.sender (as in the mutant),
        // the transfer would fail and go() would revert.
        assert(!reverted);
    }
    receive() external payable {
        sink = block.number + msg.value; // storage write: exceeds 2300 gas stipend
    }
}

